void VSwmmacF3216x16x128Fp8Fp8Vop3p::build_modifiers(std::string &out) const {
  if (inst_.opsel & 0x1)
    out += " index_key:1";
  if (inst_.opsel & 0x4)
    out += " matrix_a_reuse";
  if (inst_.pad_14)
    out += " matrix_b_reuse";
}

